.contact_list {
    &__wrapper {
        display: flex;
        flex-direction: column;
        height: 100%;
        overflow: hidden;
    }

    &__content {
        flex: 1;
        min-height: 0;
        overflow-y: hidden;
    }

    &__no-results {
        display: flex;
        align-items: center;
        justify-content: center;
        height: 100%;
        padding: 24px;
        color: var(--text-medium);
        font: var(--web-body-medium);
        text-align: center;
    }

    &__section_heading {
        display: flex;
        align-items: center;
        margin-top: 16px;
        padding: 8px;
        color: var(--text-medium);
        font: var(--web-sm-semibold);
        gap: 4px;
    }

    &__all_chats_heading {
        justify-content: space-between;
        margin-top: 4px;
        padding-top: 12px;
    }

    &__pinned {
        display: flex;
        gap: 4px;
        align-items: center;
    }
}

@media (width < $md) {
    .contact_list {
        &__wrapper {
            flex: 1;
            min-height: 0;
            overflow-y: auto;
        }

        &__content {
            flex: none;
            overflow-y: visible;
        }

        &__section_heading {
            margin-top: 0;
        }
    }
}

