    cursor: grab;

    &:hover {
        color: var(--text-default);
    }

    &:focus {
        outline: 2px solid var(--brand);
        outline-offset: 2px;
    }

    &:active {
        cursor: grabbing;
    }
}

.phase_name {
    min-width: 0;
    margin: 0;
    color: var(--text-strong);
    font: var(--web-lg-semibold);
}

// Read-only cue on the title row that this phase has an automation; the
// clickable bolt lives in the floating action cluster.
.automation_indicator {
    flex-shrink: 0;
    color: var(--brand);
}

.description_info {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    padding: 2px;
    border: none;
    border-radius: 6px;
    background: none;
    color: var(--icon-default);
    cursor: help;

    &:hover {
        color: var(--text-default);
    }

    &:focus {
        outline: 2px solid var(--brand);
        outline-offset: 2px;
    }
}

// The action cluster floats over the top-right of the header instead of
// sharing the title row, so long phase names keep the full width. It only
// shows while the pointer is over the column (or a button inside has focus).
.title_actions {
    display: flex;
    position: absolute;
    top: 10px;
    right: 12px;
    align-items: center;
    padding: 2px 4px;
    transition: opacity 0.15s ease-in-out;
    border: 1px solid var(--border-default);
    border-radius: 8px;
    opacity: 0;
    background-color: var(--bg-default);
    gap: 4px;
    pointer-events: none;

    &:focus-within {
        opacity: 1;
        pointer-events: auto;
    }
}

:global(.pathway_column):hover .title_actions {
    opacity: 1;
    pointer-events: auto;
}

// Touch devices have no hover, so the actions stay visible there.
@media (hover: none) {
    .title_actions {
        opacity: 1;
        pointer-events: auto;
    }
}

.automations_button,
.edit_button {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 4px;
    transition: color 0.15s ease-in-out;
    border: none;
    border-radius: 6px;
    background: none;
    color: var(--icon-default);
    cursor: pointer;

    &:hover {
        color: var(--text-default);
    }

    &:focus {
        outline: 2px solid var(--brand);
        outline-offset: 2px;
    }
}

// Phases that already have an automation get a filled, brand-colored lightning.
.automations_button_active {
    color: var(--brand);

    &:hover {
        color: var(--brand);
    }
}

.delete_button {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 4px;
    transition: color 0.15s ease-in-out;
    border: none;
    border-radius: 6px;
    background: none;
    color: var(--icon-default);
    cursor: pointer;

    &:hover {
        color: var(--text-danger-default);
    }

    &:focus {
        outline: 2px solid var(--text-danger-default);
        outline-offset: 2px;
    }
}

.edit_form {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.edit_actions {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
}

// CommonTooltip is a no-op on mobile, so the info icon would do nothing there.
@media (width < $md) {
    .description_info {
        display: none;
    }
}

