import type { PinnedChannel } from 'called-api/src/openApi/calledApiSchemas';

/**
 * The backend stores one `order` number per pinned channel and the frontend
 * renders by that number. Every write therefore renumbers the whole array
 * densely (order = index) so gaps and collisions can never accumulate:
 * unpinning a middle pin must not leave a hole, and a fresh pin must always
 * land at the end, below older pins.
 */

export const renumberPinnedChannels = (pinned: PinnedChannel[]): PinnedChannel[] =>
    [...pinned]
        .sort((a, b) => a.order - b.order)
        .map((pin, index) => ({ ...pin, order: index }));

export const addPinnedChannel = (pinned: PinnedChannel[], channelUrl: string): PinnedChannel[] => {
    if (pinned.some(pin => pin.channel === channelUrl)) {
        return renumberPinnedChannels(pinned);
    }
    return renumberPinnedChannels([...pinned, { order: pinned.length, channel: channelUrl }]);
};

export const removePinnedChannel = (pinned: PinnedChannel[], channelUrl: string): PinnedChannel[] =>
    renumberPinnedChannels(pinned.filter(pin => pin.channel !== channelUrl));

export const toPinnedChannels = (channelUrls: string[]): PinnedChannel[] =>
    channelUrls.map((channel, index) => ({ order: index, channel }));
```

