import { describe, it, expect } from 'vitest';
import type { PinnedChannel } from 'called-api/src/openApi/calledApiSchemas';
import {
    addPinnedChannel,
    removePinnedChannel,
    renumberPinnedChannels,
    toPinnedChannels,
} from '../pinnedChannels';

const pin = (channel: string, order: number): PinnedChannel => ({ order, channel });

describe('renumberPinnedChannels', () => {
    it('sorts by stored order and renumbers densely', () => {
        expect(renumberPinnedChannels([pin('d', 3), pin('b', 0), pin('e', 4), pin('c', 2)]))
            .toEqual([
                pin('b', 0),
                pin('c', 1),
                pin('d', 2),
                pin('e', 3),
            ]);
    });

    it('does not mutate the input array', () => {
        const input = [pin('b', 0), pin('a', 1)];

        renumberPinnedChannels(input);

        expect(input).toEqual([pin('b', 0), pin('a', 1)]);
    });

    it('is stable when the input is already dense', () => {
        const input = [pin('a', 0), pin('b', 1), pin('c', 2)];

        expect(renumberPinnedChannels(input)).toEqual(input);
    });
});

describe('addPinnedChannel', () => {
    it('appends a new pin at the end of the list', () => {
        expect(addPinnedChannel([pin('a', 0), pin('b', 1)], 'c'))
            .toEqual([pin('a', 0), pin('b', 1), pin('c', 2)]);
    });

    it('lands a new pin below older pins when stored orders have gaps', () => {
        // Pin A, B, C, D (orders 0-3); unpin A and C without renumbering,
        // leaving D at order 3. E and F must still sort below D.
        let pinned = [pin('b', 0), pin('d', 3)];
        pinned = addPinnedChannel(pinned, 'e');
        pinned = addPinnedChannel(pinned, 'f');

        expect(pinned).toEqual([
            pin('b', 0),
            pin('d', 1),
            pin('e', 2),
            pin('f', 3),
        ]);
    });

    it('does not duplicate a pin that is already present', () => {
        expect(addPinnedChannel([pin('a', 0)], 'a')).toEqual([pin('a', 0)]);
    });
});

describe('removePinnedChannel', () => {
