import { useCallback, useState } from 'react';
import { arrayMove } from '@dnd-kit/sortable';
import { enqueueSnackbar } from 'notistack';
import type { PinnedChannel } from 'called-api/src/openApi/calledApiSchemas';
import { toPinnedChannels } from '@/utils/pinnedChannels';

type UsePinnedChannelsEditParams = {
    /** Saved pins in stored order (the server source of truth). */
    savedPinnedChannels: PinnedChannel[];
    /** Persists a full renumbered pinnedChannels array in one request. */
    savePinnedChannels: (pinnedChannels: PinnedChannel[]) => Promise<void>;
};

/**
 * Edit mode for the pinned section: a draft order of channel urls that the
 * list sorts by while editing. Save persists the draft in one request;
 * Cancel discards it without writing.
 */
export const usePinnedChannelsEdit = ({ savedPinnedChannels, savePinnedChannels }: UsePinnedChannelsEditParams) => {
    const [isEditing, setIsEditing] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [draftChannels, setDraftChannels] = useState<string[]>([]);

    const startEdit = useCallback(() => {
        setDraftChannels(savedPinnedChannels.map((pin) => pin.channel));
        setIsEditing(true);
    }, [savedPinnedChannels]);

    const cancelEdit = useCallback(() => {
        setIsEditing(false);
        setDraftChannels([]);
    }, []);

    const saveEdit = useCallback(async () => {
        if (isSaving) {
            return;
        }
        setIsSaving(true);
        try {
            await savePinnedChannels(toPinnedChannels(draftChannels));
            setIsEditing(false);
        } catch {
            enqueueSnackbar('Failed to save pinned channels. Please try again.', { variant: 'error' });
        } finally {
            setIsSaving(false);
        }
    }, [draftChannels, isSaving, savePinnedChannels]);

    const toggleChannel = useCallback((channelUrl: string) => {
        setDraftChannels(prevChannels => prevChannels.includes(channelUrl)
            ? prevChannels.filter(url => url !== channelUrl)
            : [...prevChannels, channelUrl]);
    }, []);

    const reorderChannels = useCallback((activeUrl: string, overUrl: string) => {
        if (activeUrl === overUrl) {
            return;
        }
        setDraftChannels(prevChannels => {
            const oldIndex = prevChannels.indexOf(activeUrl);
            const newIndex = prevChannels.indexOf(overUrl);
            if (oldIndex < 0 || newIndex < 0) {
                return prevChannels;
            }
            return arrayMove(prevChannels, oldIndex, newIndex);
        });
    }, []);

    /** Drop a pin the server just removed (channel deleted or left). */
    const dropChannel = useCallback((channelUrl: string) => {
        setDraftChannels(prevChannels => prevChannels.filter(url => url !== channelUrl));
    }, []);

    return {
        isEditing,
        isSaving,
        draftChannels,
        startEdit,
        cancelEdit,
        saveEdit,
        toggleChannel,
        reorderChannels,
        dropChannel,
    };
};

