import { renderHook, act } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import type { PinnedChannel } from 'called-api/src/openApi/calledApiSchemas';
import { usePinnedChannelsEdit } from '../usePinnedChannelsEdit';

const mockEnqueueSnackbar = vi.fn();
vi.mock('notistack', () => ({
    enqueueSnackbar: (message: string, options: { variant: string }): void => {
        mockEnqueueSnackbar(message, options);
    },
}));

const SAVED_PINS: PinnedChannel[] = [
    { order: 0, channel: 'b' },
    { order: 1, channel: 'd' },
];

const renderPinnedEdit = (savePinnedChannels = vi.fn().mockResolvedValue(undefined)) => renderHook(
    () => usePinnedChannelsEdit({
        savedPinnedChannels: SAVED_PINS,
        savePinnedChannels,
    }),
);

describe('usePinnedChannelsEdit', () => {
    beforeEach(() => {
        mockEnqueueSnackbar.mockReset();
    });

    it('seeds the draft from the saved pin order on start', () => {
        const { result } = renderPinnedEdit();

        expect(result.current.isEditing).toBe(false);

        act(() => {
            result.current.startEdit();
        });

        expect(result.current.isEditing).toBe(true);
        expect(result.current.draftChannels).toEqual(['b', 'd']);
    });

    it('toggles channels into and out of the draft', () => {
        const { result } = renderPinnedEdit();
        act(() => {
            result.current.startEdit();
        });

        act(() => {
            result.current.toggleChannel('e');
        });
        expect(result.current.draftChannels).toEqual(['b', 'd', 'e']);

        act(() => {
            result.current.toggleChannel('b');
        });
        expect(result.current.draftChannels).toEqual(['d', 'e']);
    });

    it('reorders the draft when channels are dragged', () => {
        const { result } = renderPinnedEdit();
        act(() => {
            result.current.startEdit();
        });

        act(() => {
            result.current.reorderChannels('d', 'b');
        });
        expect(result.current.draftChannels).toEqual(['d', 'b']);

        act(() => {
            result.current.reorderChannels('b', 'b');
        });
        expect(result.current.draftChannels).toEqual(['d', 'b']);
    });

    it('saves one densely renumbered array and exits edit mode', async () => {
        const savePinnedChannels = vi.fn().mockResolvedValue(undefined);
        const { result } = renderPinnedEdit(savePinnedChannels);
        act(() => {
            result.current.startEdit();
        });
        act(() => {
            result.current.toggleChannel('e');
        });
        act(() => {
            result.current.reorderChannels('d', 'b');
        });

        await act(async () => {
            await result.current.saveEdit();
        });

        expect(savePinnedChannels).toHaveBeenCalledTimes(1);
        expect(savePinnedChannels).toHaveBeenCalledWith([
            { order: 0, channel: 'd' },
            { order: 1, channel: 'b' },
            { order: 2, channel: 'e' },
        ]);
        expect(result.current.isEditing).toBe(false);
        expect(result.current.isSaving).toBe(false);
    });

    it('cancels without writing and discards the draft', () => {
        const savePinnedChannels = vi.fn();
        const { result } = renderPinnedEdit(savePinnedChannels);
        act(() => {
            result.current.startEdit();
        });
        act(() => {
            result.current.toggleChannel('e');
        });

        act(() => {
            result.current.cancelEdit();
        });

        expect(savePinnedChannels).not.toHaveBeenCalled();
        expect(result.current.isEditing).toBe(false);
        expect(result.current.draftChannels).toEqual([]);
    });

    it('stays in edit mode and reports the error when the save fails', async () => {
        const savePinnedChannels = vi.fn().mockRejectedValue(new Error('network'));
        const { result } = renderPinnedEdit(savePinnedChannels);
        act(() => {
            result.current.startEdit();
        });

        await act(async () => {
            await result.current.saveEdit();
        });

        expect(result.current.isEditing).toBe(true);
        expect(result.current.isSaving).toBe(false);
        expect(result.current.draftChannels).toEqual(['b', 'd']);
        expect(mockEnqueueSnackbar).toHaveBeenCalledWith(
            'Failed to save pinned channels. Please try again.',
            { variant: 'error' }
        );
    });

    it('ignores a second save while the first is in flight', async () => {
        let resolveSave: () => void = () => undefined;
        const savePinnedChannels = vi.fn(
            () => new Promise<void>(resolve => {
                resolveSave = resolve;
            })
        );
        const { result } = renderPinnedEdit(savePinnedChannels);
        act(() => {
            result.current.startEdit();
        });

        const firstSave = act(async () => {
            result.current.saveEdit();
        });
        const secondSave = act(async () => {
            result.current.saveEdit();
        });

        resolveSave();
        await firstSave;
        await secondSave;

        expect(savePinnedChannels).toHaveBeenCalledTimes(1);
        expect(result.current.isEditing).toBe(false);
    });

    it('drops a channel the server removed from the draft', () => {
        const { result } = renderPinnedEdit();
        act(() => {
            result.current.startEdit();
        });

        act(() => {
            result.current.dropChannel('b');
        });

        expect(result.current.draftChannels).toEqual(['d']);
    });
});

